/* Evidence-aware dynasty accents and annual calendar context. */
(function(scope){
'use strict';
let data={dynasties:[],sources:{}},getPeers=null;
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
function family(value){const title=typeof value==='string'?value:value?.properties?.title||'';if(['汉','西汉','东汉','汉（郡国并行）','汉（刘邦）'].includes(title))return '汉';if(['晋','西晋','东晋'].includes(title))return '晋';if(['唐','唐（李渊）','唐 · 岐（关中）'].includes(title))return '唐';if(['宋','北宋','南宋','南宋（闽广行朝）'].includes(title))return '宋';return ['秦','隋','元','明','清'].includes(title)?title:'';}
function get(value,year){const key=family(value);if(!key)return null;const record=data.dynasties.find(d=>d.key===key&&year>=d.from&&year<=d.to);return record?{...record,hex:record.displayHex||record.hex}:null;}
function init(input,context){data=input;getPeers=context.getPeers||null;const dialog=document.getElementById('colorDialog');document.getElementById('colorEvidenceBtn').onclick=()=>{context.stop();if(document.getElementById('colorEvidenceBtn').dataset.ancient==='true'){document.getElementById('ancientDialog').showModal();return;}dialog.showModal();};document.getElementById('closeColor').onclick=()=>dialog.close();document.getElementById('dynastyColorList').innerHTML=data.dynasties.map(d=>'<article class="color-record" style="--record-color:'+esc(d.displayHex||d.hex)+'"><div class="color-record-head"><i aria-hidden="true"></i><h3>'+esc(d.label)+'</h3><span>'+esc(d.colorName)+'</span></div><small>'+esc(d.displayName?'界面：'+d.displayName+'；文献：'+d.colorName+' · '+(d.basis||d.confidence):d.basis||d.confidence)+'</small><p>'+esc(d.note)+'</p><div class="color-record-sources">'+(d.sourceIds||[]).map(id=>data.sources[id]).filter(Boolean).map(s=>'<a href="'+esc(s.url)+'" target="_blank" rel="noopener">'+esc(s.title)+' ↗</a>').join('')+'</div></article>').join('');}
function update(feature,info,year){const tone=get(feature,year),accent=tone?.hex||'#60775b';document.documentElement.style.setProperty('--dynasty-accent',accent);const rgb=[1,3,5].map(i=>parseInt(accent.slice(i,i+2),16));document.documentElement.style.setProperty('--dynasty-button-ink',rgb[0]*.299+rgb[1]*.587+rgb[2]*.114>145?'#34452f':'#fffaf0');const card=document.getElementById('emperorReadout');card.style.setProperty('--court-accent',accent);const badge=document.getElementById('colorEvidenceBtn');badge.innerHTML='<i aria-hidden="true" style="background:'+accent+'"></i>'+esc(tone?(tone.displayName||tone.colorName)+' · '+(tone.displayBasis||tone.basis||'配色依据'):'朝代配色')+' <span>↗</span>';badge.title='查看历代配色依据；界面色值为现代设计取色';badge.dataset.ancient=year<-221?'true':'false';if(year<-221){badge.innerHTML='<i style="background:#9b8971"></i>先秦图例与依据 ↗';badge.title='查看约年、考古遗址与战国形势图的区别';}const eraNode=document.getElementById('mapEra');const peers=getPeers?getPeers():[{feature,info,color:accent}];const rows=[],seen=new Set();for(const peer of peers){const eras=[...new Set(scope.EmperorLineage.identities(peer.info,year).map(p=>p.era).filter(Boolean).flatMap(e=>e.split('／')))];if(!eras.length)continue;const original=peer.feature.properties.displayTitle||peer.feature.properties.title;const name=original==='刘备势力'&&year>=221?'蜀汉':original==='孙权势力'&&year>=229?'孙吴':year>=690&&year<=704&&original==='唐'?'武周':original;const key=name+'|'+eras.join('／');if(seen.has(key))continue;seen.add(key);rows.push({name,eras,color:peer.color||accent});}eraNode.hidden=!rows.length;eraNode.classList.toggle('map-era-parallel',rows.length>1);eraNode.innerHTML=rows.map(row=>'<div class="map-era-row" style="--era-color:'+esc(row.color)+'"><span>'+esc(row.name)+'</span><b>'+esc(row.eras.join('／'))+'</b></div>').join('');eraNode.title='同年并存政权的已核纪年；同年改元可并列。';const yearBox=document.getElementById('yearMark');document.getElementById('mapWrap').classList.toggle('song-court-layout',card.dataset.courtLayout==='song-sides'&&card.classList.contains('parallel-courts'));card.style.setProperty('--song-court-height',Math.max(130,document.getElementById('mapWrap').clientHeight-44)+'px');card.style.top=Math.max(150,yearBox.offsetTop+yearBox.offsetHeight+18)+'px';card.style.maxHeight=Math.max(100,document.getElementById('mapWrap').clientHeight-card.offsetTop-22)+'px';yearBox.setAttribute('aria-label',(year<-841?'约公元前':year<0?'公元前':'公元')+Math.abs(year)+'年'+(rows.length?'，'+rows.map(row=>row.name+' '+row.eras.join('／')).join('，'):''));}
function barStyle(key,from,to){const axis=y=>y<0?y:y-1,start=axis(from),length=axis(to)-start+1;const ranges=data.dynasties.filter(d=>d.key===family(key)&&d.to>=from&&d.from<=to).sort((a,b)=>a.from-b.from);if(ranges.length<2)return '';return 'linear-gradient(to right,'+ranges.flatMap(d=>[(d.displayHex||d.hex)+' '+Math.max(0,(axis(d.from)-start)/length*100)+'%',(d.displayHex||d.hex)+' '+Math.min(100,(axis(d.to)-start+1)/length*100)+'%']).join(',')+')';}
const api={family,get,init,update,barStyle};scope.AtlasDesign=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
